import{_ as e,o as n,c as a,ah as i}from"./chunks/framework.D4KxWb5R.js";const u=JSON.parse('{"title":"By position","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/positions.md","filePath":"src/en/guide/positions.md"}'),r={name:"en/guide/positions.md"};function d(s,t,l,o,c,h){return n(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="by-position" tabindex="-1">By position <a class="header-anchor" href="#by-position" aria-label="Permalink to &quot;By position&quot;">​</a></h1><p>Two independent settings decide what you see:</p><ul><li>your <strong>position</strong> decides the <strong>functions</strong> (the entries of the Administration menu);</li><li>your <strong>scope</strong> decides the <strong>data</strong> visible in those functions and in the intranet.</li></ul><p>A change of position or scope takes effect immediately, on your next action, without a new invitation or signing in again.</p><h2 id="the-seven-positions" tabindex="-1">The seven positions <a class="header-anchor" href="#the-seven-positions" aria-label="Permalink to &quot;The seven positions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Position</th><th>Scope</th></tr></thead><tbody><tr><td>Managing Director (CEO)</td><td>All products, all zones</td></tr><tr><td>Head of Product Operations &amp; Finance</td><td>All products, all zones</td></tr><tr><td>Head of Partner &amp; Customer Support</td><td>All products, all zones</td></tr><tr><td>Support L1 — Customers</td><td>Assigned products, zones and offices (at least one product)</td></tr><tr><td>Support L2 — Providers, Partners &amp; Moderation</td><td>Assigned products, zones and offices (at least one product)</td></tr><tr><td>HR &amp; Legal Affairs</td><td>Cross-cutting: all offices, no product</td></tr><tr><td>Finance &amp; Accounting</td><td>Cross-cutting: all offices, no product</td></tr></tbody></table><p>A member of a <a href="./administration/teams.html">team</a> also sees the team&#39;s products, whatever their position.</p><h2 id="function-matrix" tabindex="-1">Function matrix <a class="header-anchor" href="#function-matrix" aria-label="Permalink to &quot;Function matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Function</th><th style="text-align:center;">CEO</th><th style="text-align:center;">Product Operations</th><th style="text-align:center;">Support head</th><th style="text-align:center;">Support L1</th><th style="text-align:center;">Support L2</th><th style="text-align:center;">HR</th><th style="text-align:center;">Finance</th></tr></thead><tbody><tr><td>Desk, communications, resources (intranet)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td><a href="./administration/communications.html">Publish communications</a></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td><a href="./administration/communications.html#shared-resources">Manage shared resources</a></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td><a href="./administration/site-pages.html">Public site pages</a></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td><a href="./administration/contact-messages.html">Contact messages</a></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td><a href="./administration/registry.html">Registry: products and zones</a></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td><a href="./administration/indicators.html">Indicator supervision</a></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td></tr><tr><td><a href="./administration/logs.html">Sync log</a></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td><a href="./administration/accounts.html#disabling-an-account">Offboarding (disable an account)</a></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td><a href="./administration/accounts.html">Accounts: invite, position, scope, access</a></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td><a href="./administration/referentials.html">Offices, departments, teams</a></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td><a href="./administration/settings.html">Configuration and indicator definitions</a></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td><a href="./administration/registry.html#integrating-a-product">Product integration (SSO, API)</a></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td><a href="./administration/logs.html">Audit log</a></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><p>Most of the work of Support L1, Support L2, HR and Finance happens in the product back-offices; the intranet opens them through SSO when you are granted access.</p><h2 id="managing-director-ceo" tabindex="-1">Managing Director (CEO) <a class="header-anchor" href="#managing-director-ceo" aria-label="Permalink to &quot;Managing Director (CEO)&quot;">​</a></h2><p>The CEO has every function: they are the general administrator. They invite accounts, grant access to product back-offices, and manage the configuration, the referentials and product integration. The last active CEO account can neither change position nor be disabled.</p><h2 id="product-operations-finance" tabindex="-1">Product Operations &amp; Finance <a class="header-anchor" href="#product-operations-finance" aria-label="Permalink to &quot;Product Operations &amp; Finance&quot;">​</a></h2><ul><li>Keep the <a href="./administration/registry.html">registry</a>: register and edit products, qualify zones.</li><li>Follow the <a href="./administration/indicators.html">supervision</a> of consolidated indicators.</li><li>Check the <a href="./administration/logs.html">sync log</a> between the registry and the product back-offices.</li></ul><h2 id="partner-customer-support" tabindex="-1">Partner &amp; Customer Support <a class="header-anchor" href="#partner-customer-support" aria-label="Permalink to &quot;Partner &amp; Customer Support&quot;">​</a></h2><ul><li><a href="./administration/communications.html">Publish communications</a> to targeted recipients and manage <a href="./administration/communications.html#shared-resources">shared resources</a>.</li><li>Edit the <a href="./administration/site-pages.html">public site pages</a>.</li><li>Handle <a href="./administration/contact-messages.html">contact messages</a>, like Support L1.</li></ul><h2 id="support-l1-—-customers" tabindex="-1">Support L1 — Customers <a class="header-anchor" href="#support-l1-—-customers" aria-label="Permalink to &quot;Support L1 — Customers&quot;">​</a></h2><ul><li>Handle the queue of <a href="./administration/contact-messages.html">contact messages</a> from the public site. The queue is shared by every Support L1 and the Support head, with no filter by product or zone.</li><li>Handle customer requests in the back-offices of the products you are granted.</li></ul><h2 id="support-l2-—-providers-partners-moderation" tabindex="-1">Support L2 — Providers, Partners &amp; Moderation <a class="header-anchor" href="#support-l2-—-providers-partners-moderation" aria-label="Permalink to &quot;Support L2 — Providers, Partners &amp; Moderation&quot;">​</a></h2><p>No administration function in M&#39;City IQ. Moderation and the follow-up of providers and partners happen in the product back-offices of your scope, opened from their <a href="./desk.html#product-spaces">product spaces</a>.</p><h2 id="hr-legal-affairs" tabindex="-1">HR &amp; Legal Affairs <a class="header-anchor" href="#hr-legal-affairs" aria-label="Permalink to &quot;HR &amp; Legal Affairs&quot;">​</a></h2><ul><li>Disable the account of someone leaving M&#39;City, from <a href="./administration/accounts.html#disabling-an-account">Offboarding</a>.</li><li>HR files and contracts stay outside the platform.</li></ul><h2 id="finance-accounting" tabindex="-1">Finance &amp; Accounting <a class="header-anchor" href="#finance-accounting" aria-label="Permalink to &quot;Finance &amp; Accounting&quot;">​</a></h2><ul><li>Check the <a href="./administration/indicators.html">supervision</a> of consolidated indicators.</li><li>A product&#39;s payments and accounting are viewed in its back-office.</li></ul>',24)])])}const p=e(r,[["render",d]]);export{u as __pageData,p as default};
